from collections import deque

def distances(graphe, depart):
    dist = {depart: 0}
    file = deque([depart])
    while file:
        ville = file.popleft()
        for voisin in graphe[ville]:
            if voisin not in dist:
                dist[voisin] = dist[ville] + 1
                file.append(voisin)
    return dist

